bool filename_is_valid(const char *p) { /* <=== filename_is_valid */ 
        const char *e;

        if (isempty(p))
                return false;

        if (dot_or_dot_dot(p))
                return false;

        e = strchrnul(p, '/');
        if (*e != 0)
                return false;

        if (e - p > NAME_MAX) /* NAME_MAX is counted *without* the trailing NUL byte */
                return false;

        return true;
}

struct dirent *readdir_ensure_type(DIR *d) { /* <=== readdir_ensure_type */ 
        int r;

        assert(d);

        /* Like readdir(), but fills in .d_type if it is DT_UNKNOWN */

        for (;;) {
                struct dirent *de;

                errno = 0;
                de = readdir(d);
                if (!de)
                        return NULL;

                r = dirent_ensure_type(d, de);
                if (r >= 0)
                        return de;
                if (r != -ENOENT) {
                        errno = -r; /* We want to be compatible with readdir(), hence propagate error via errno here */
                        return NULL;
                }

                /* Vanished by now? Then skip immediately to next */
        }
}

bool dot_or_dot_dot(const char *path) { /* <=== dot_or_dot_dot */ 
        if (!path)
                return false;
        if (path[0] != '.')
                return false;
        if (path[1] == 0)
                return true;
        if (path[1] != '.')
                return false;

        return path[2] == 0;
}

static inline void *memcpy_safe(void *dst, const void *src, size_t n) { /* <=== memcpy_safe */ 
        if (n == 0)
                return dst;
        assert(src);
        return memcpy(dst, src, n);
