static int btrfs_ioctl_search_args_compare(const struct btrfs_ioctl_search_args *args) { /* <=== btrfs_ioctl_search_args_compare */ 
        int r;

        assert(args);

        /* Compare min and max */

        r = CMP(args->key.min_objectid, args->key.max_objectid);
        if (r != 0)
                return r;

        r = CMP(args->key.min_type, args->key.max_type);
        if (r != 0)
                return r;

        return CMP(args->key.min_offset, args->key.max_offset);
